/* ---------- drawing helpers for this lesson (prefixed SM_ so they never clash with engine globals) ---------- */
const SM_GR='#5C6577', SM_LG='#ADB5BD', SM_CU='#D08C3F', SM_BD='#2F7D4F', SM_SB='#E3F1E6';
const SM_F='font-family="Nunito Sans, sans-serif"';
const SM_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${SM_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}">${t}</text>`;
const SM_L=(x1,y1,x2,y2,col=SM_GR,w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const SM_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"/>`;
const SM_head=(x1,y1,x2,y2,col,h=16)=>{const a=Math.atan2(y2-y1,x2-x1);return `<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const SM_ar=(x1,y1,x2,y2,col='#18213A',w=4,h=16)=>{const a=Math.atan2(y2-y1,x2-x1);return SM_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+SM_head(x1,y1,x2,y2,col,h)};
const SM_dot=(x,y,col,r=8)=>`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r}" fill="${col}" stroke="#FFFFFF" stroke-width="2"/>`;
/* Smith chart geometry: Γ = (z − 1)/(z + 1) for z = r + jx; screen y grows down, so Im Γ is drawn upwards */
const SM_G=(r,x)=>{const d=(r+1)*(r+1)+x*x;return [(r*r+x*x-1)/d,2*x/d]};
const SM_P=(cx,cy,R,r,x)=>{const [u,v]=SM_G(r,x);return [cx+R*u,cy-R*v]};
const SM_chart=(cx,cy,R,o={})=>{const lc=o.lc||SM_LG;let s=`<circle cx="${cx}" cy="${cy}" r="${R}" fill="#FFFFFF" stroke="${o.rim||INK}" stroke-width="${o.rw||2.5}"/>`+SM_L(cx-R,cy,cx+R,cy,lc,1.5);
 [0.5,1,2].forEach(r=>{s+=`<circle cx="${(cx+R*r/(1+r)).toFixed(1)}" cy="${cy}" r="${(R/(1+r)).toFixed(1)}" fill="none" stroke="${lc}" stroke-width="1.5"/>`});
 const rs=[0,.08,.16,.26,.38,.5,.7,1,1.4,2,3,5,9,20,80];
 [0.5,1,2,-0.5,-1,-2].forEach(x=>{s+=`<polyline points="${rs.map(r=>SM_P(cx,cy,R,r,x).map(v=>v.toFixed(1)).join(',')).join(' ')}" fill="none" stroke="${lc}" stroke-width="1.5"/>`});
 return s};
/* an arc of radius rad round (cx,cy) from angle a0 to a1 (degrees, Γ-plane, anticlockwise positive), with an arrowhead at a1 */
const SM_arc=(cx,cy,rad,a0,a1,col,w=4,head=true,dash='')=>{const n=48,p=[];for(let i=0;i<=n;i++){const a=(a0+(a1-a0)*i/n)*Math.PI/180;p.push([cx+rad*Math.cos(a),cy-rad*Math.sin(a)])}
 const q=head?p.slice(0,n-1):p;let s=`<polyline points="${q.map(v=>v[0].toFixed(1)+','+v[1].toFixed(1)).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round"${dash?` stroke-dasharray="${dash}"`:''}/>`;
 if(head){const [x1,y1]=p[n-3],[x2,y2]=p[n];s+=SM_head(x1,y1,x2,y2,col,18)}return s};
const SM_sine=(x0,len,yc,amp,col,w=4)=>{let p=[];for(let i=0;i<=80;i++){p.push(`${(x0+len*i/80).toFixed(1)},${(yc-amp*Math.sin(2*Math.PI*i/80)).toFixed(1)}`)}return `<polyline points="${p.join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round"/>`};
const SM_dim=(x1,x2,y,col,lab,fs=22)=>SM_L(x1,y,x2,y,col,2)+SM_L(x1,y-9,x1,y+9,col,2)+SM_L(x2,y-9,x2,y+9,col,2)+SM_T((x1+x2)/2,y+fs+8,lab,{fs,fw:800,a:'middle',fill:col});
/* a microstrip cross-section: substrate x..x+w, top at y, height h; strip of width sw centred; fringe=true adds field lines through the air */
const SM_ms=(x,y,w,h,sw,o={})=>{const xm=x+w/2,a=xm-sw/2,b=xm+sw/2,fc=o.fc||ORG;let s=`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${SM_SB}"/><rect x="${x}" y="${y+h}" width="${w}" height="10" fill="${INK}"/><rect x="${a}" y="${y-10}" width="${sw}" height="10" fill="${BLU}"/>`;
 if(o.field){[.2,.5,.8].forEach(f=>{const xx=a+sw*f;s+=SM_ar(xx,y+3,xx,y+h-2,fc,2.5,12)})}
 if(o.fringe){const d=o.fd||sw*.55;s+=`<path d="M${a+2},${y-8} C${a-d*.6},${y-d*.9} ${a-d},${y-d*.5} ${a-d},${y+h-14}" fill="none" stroke="${fc}" stroke-width="2.5"/>`+SM_head(a-d,y+h-30,a-d,y+h-2,fc,12)
  +`<path d="M${b-2},${y-8} C${b+d*.6},${y-d*.9} ${b+d},${y-d*.5} ${b+d},${y+h-14}" fill="none" stroke="${fc}" stroke-width="2.5"/>`+SM_head(b+d,y+h-30,b+d,y+h-2,fc,12)}
 return s};

